function therapistEscape(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function therapistMaskPhone(phone){return String(phone).replace(/^(\d{3})\d{4}(\d{4})$/,'$1****$2')}
function therapistCustomer(id){return therapistCustomerData.find(customer=>customer.id===id)}
function therapistAppointment(id){return therapistAppointments.find(appointment=>appointment.id===id)}
function therapistServiceOrder(id){return therapistCustomerData.flatMap(customer=>customer.orders).find(order=>order.id===id)}
function therapistCompletedSessions(order){if(!order)return 0;const related=therapistAppointments.filter(item=>item.orderId===order.id),inProgressRedemptions=related.filter(item=>item.redeemed&&item.status!=='已完成').length,pendingUnredeemed=related.filter(item=>item.status==='待核销'&&!item.redeemed&&item.type==='服务').length,savedNotes=st.therapistRecords.filter(record=>record.type==='康复纪要'&&(record.orderId===order.id||therapistAppointment(record.appointmentId)?.orderId===order.id)).length;return Math.max(Math.max(0,order.used-inProgressRedemptions)+pendingUnredeemed,savedNotes)}
function therapistNeedsSummary(appointment){const order=therapistServiceOrder(appointment?.orderId);return (st.employeeTab==='therapistRecordForm'&&!!st.therapistForceSummary)||(appointment?.type==='服务'&&!!order&&(therapistCompletedSessions(order)+1)%5===0)}
function therapistAppointmentDetail(){
  const item=therapistAppointment(st.therapistAppointmentId);if(!item)return '<div class="empty">未找到预约订单</div>';
  const order=therapistServiceOrder(item.orderId),customer=therapistCustomer(item.customerId),isManager=st.employeeRole==='店长',technical=st.employeeType==='技术型店长',assignedToManager=item.assignedTo===managerStaffName()||item.assignedTo==='技术型店长',unitPrice=Number(S.find(service=>service[0]===item.service)?.[3])||0,totalPrice=unitPrice*(order?.total||1),amountPaid=totalPrice,redeemHistory=order?.records||[];let actions='';
  if(isManager){
    if(item.status==='待核销')actions=`<button class="textbtn therapist-action" data-act="therapistArchive" data-customer="${item.customerId}">查看档案</button><button class="textbtn therapist-action" data-act="therapistScan" data-id="${item.id}">扫码核销</button>`;
    else if(item.status==='待服务')actions=`${technical&&assignedToManager?`<button class="textbtn therapist-action" data-act="therapistStart" data-id="${item.id}">${item.type==='评估'?'开始评估':'开始服务'}</button>`:''}<button class="textbtn therapist-action" data-act="therapistArchive" data-customer="${item.customerId}">查看档案</button><button class="textbtn therapist-action" data-act="managerChangeCoach" data-id="${item.id}">更换康复师</button>`;
    else if(item.status==='服务中'&&technical&&assignedToManager)actions=`<button class="textbtn therapist-action" data-act="therapistFillRecord" data-id="${item.id}">${item.type==='评估'?'填写评估资料':therapistNeedsSummary(item)?'填写康复纪要与小结':'填写康复纪要'}</button>${item.redeemed?'':`<button class="textbtn therapist-action" data-act="therapistScan" data-id="${item.id}">扫码核销</button>`}`;
    else actions=`<button class="textbtn therapist-action" data-act="therapistArchive" data-customer="${item.customerId}">查看档案</button>${item.status==='已完成'?'':`<button class="textbtn therapist-action" data-act="managerChangeCoach" data-id="${item.id}">更换康复师</button>`}`;
  }else actions=item.status==='待服务'?`<button class="textbtn therapist-action" data-act="therapistArchive" data-customer="${item.customerId}">查看档案</button><button class="textbtn therapist-action" data-act="therapistStart" data-id="${item.id}">${item.type==='评估'?'开始评估':'开始服务'}</button>${item.redeemed?'':`<button class="textbtn therapist-action" data-act="therapistScan" data-id="${item.id}">核销订单</button>`}`:item.status==='服务中'?`<button class="textbtn therapist-action" data-act="therapistFillRecord" data-id="${item.id}">${item.type==='评估'?'填写评估资料':therapistNeedsSummary(item)?'填写康复纪要与小结':'填写康复纪要'}</button>${item.redeemed?'':`<button class="textbtn therapist-action" data-act="therapistScan" data-id="${item.id}">核销订单</button>`}`:item.status==='待核销'?`<button class="textbtn therapist-action" data-act="therapistScan" data-id="${item.id}">核销订单</button>`:'';
  const actionsHtml=actions?`<div class="cta order-detail-action-bar"><div class="order-actions">${actions}</div></div>`:'';
  return `<div class="employee-order-detail"><section class="card order-detail-status"><div class="between"><span class="tag ${item.status==='待核销'?'gold':''}">${item.status}</span><small class="muted">${item.type} · ${item.redeemed?'已核销':'未核销'}</small></div><p class="small">订单编号 ${order?.id||item.orderId}</p><p class="tiny muted">预约时间 ${item.date} ${item.time} · ${item.duration}</p></section><section class="card row order-product"><img class="thumb" src="${A+item.image}" alt="${item.service}"><div class="grow"><b>${item.service}</b><p>${item.type}服务 · ${item.duration} · 数量 ×${order?.total||1}</p></div><b class="price">¥${unitPrice}</b></section><section class="card small order-amount-detail"><b>优惠信息</b><div class="divider"></div><div class="between"><span>优惠券抵扣</span><span>−¥0</span></div><div class="between"><span>积分抵扣</span><span>−¥0</span></div><div class="divider"></div><div class="between"><span>订单金额</span><b>¥${totalPrice}</b></div><div class="between"><span>实付金额</span><b class="price">¥${amountPaid}</b></div></section><section class="card small order-records"><b>核销记录</b>${redeemHistory.length?redeemHistory.map(record=>`<div class="order-redemption-row"><span class="tag">已核销</span><div class="grow"><b>${record.service}</b><small>${record.time} · ${record.store} · ${record.coach}</small></div></div>`).join(''):`<p class="small muted">${item.redeemed?'核销信息暂无详细记录':'暂无核销记录'}</p>`}${item.redeemed&&item.status==='已完成'?`<p class="tiny muted">最近核销时间：${redeemHistory[0]?.time||'已完成'}</p>`:''}</section><section class="card small order-info-detail"><b>订单信息</b><p>订单编号　${order?.id||item.orderId}</p><p>下单时间　${order?.records?.[order.records.length-1]?.time?.slice(0,10)||item.date}</p><p>预约门店　${therapistStoreName()}</p><p>服务人员　${item.assignedTo||therapistStaffName()}</p><p>客户姓名　${customer?.name||item.customer}</p><p>联系电话　${customer?therapistMaskPhone(customer.phone):'—'}</p></section></div>${actionsHtml}`
}
