draw=function(){
  therapistBaseDraw();
  document.querySelectorAll('.therapist-appointment-link').forEach(link=>link.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();link.click()}}));
  if(st.page==='employee'&&['康复师','店长'].includes(st.employeeRole)){
    if(st.employeeRole==='店长'&&st.employeeTab==='therapistSchedule')st.employeeTab='managerSchedule';
    const isManager=st.employeeRole==='店长',route=st.employeeTab||(isManager?'managerWorkbench':'employee'),isPrimary=(isManager?managerPrimaryRoutes:therapistPrimaryRoutes).has(route),title=(isManager?managerRouteTitles:therapistRouteTitles)[route]||'工作台';
    const tabbar=document.getElementById('tabbar');tabbar.innerHTML=isPrimary?(isManager?managerTabNav():therapistTabNav()):'';
    tabbar.querySelectorAll('.therapist-tab').forEach(button=>button.addEventListener('click',act));
    document.getElementById('wxTitle').textContent=title;document.getElementById('topRoute').textContent=title;document.getElementById('noteTitle').textContent=title;document.getElementById('noteText').textContent=notes.employee;
    const backButton=document.getElementById('backBtn');backButton.hidden=isPrimary;backButton.onclick=therapistBack;
    document.getElementById('therapistCustomerSearch')?.addEventListener('submit',event=>{event.preventDefault();st.therapistCustomerKeyword=document.getElementById('therapistCustomerQuery').value;draw()});
    document.getElementById('therapistMonth')?.addEventListener('change',event=>{st.therapistPerformanceMonth=event.target.value;draw()});
    document.getElementById('therapistSessionNote')?.addEventListener('input',event=>{st.therapistDraft||={};st.therapistDraft.note=event.target.value});
    document.getElementById('therapistSessionSummary')?.addEventListener('input',event=>{st.therapistDraft||={};st.therapistDraft.summary=event.target.value});
    document.getElementById('therapistAssessmentResult')?.addEventListener('input',event=>{st.therapistDraft||={};st.therapistDraft.assessment=event.target.value});
    document.getElementById('therapistAssessmentPlan')?.addEventListener('input',event=>{st.therapistDraft||={};st.therapistDraft.plan=event.target.value});
    document.getElementById('therapistPeerText')?.addEventListener('input',event=>st.therapistPeerText=event.target.value);
    document.getElementById('managerComplaintResult')?.addEventListener('input',event=>st.managerComplaintDraft=event.target.value);
    document.getElementById('managerComplaintResultImage')?.addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;st.managerComplaintResultImageName=file.name;const reader=new FileReader();reader.onload=()=>{st.managerComplaintResultImageData=String(reader.result||'');draw()};reader.readAsDataURL(file)});
    document.getElementById('managerBookingCustomer')?.addEventListener('change',event=>{st.managerBookingCustomer=event.target.value;st.managerBookingOrder='';st.managerBookingCoach='';st.managerBookingDate='';st.managerBookingTime='';draw()});
    document.getElementById('managerBookingOrder')?.addEventListener('change',event=>{st.managerBookingOrder=event.target.value;st.managerBookingCoach='';st.managerBookingDate='';st.managerBookingTime='';draw()});
    document.getElementById('managerBookingCoach')?.addEventListener('change',event=>{st.managerBookingCoach=event.target.value;st.managerBookingDate='';st.managerBookingTime='';draw()});
    document.getElementById('managerBookingDate')?.addEventListener('change',event=>{st.managerBookingDate=event.target.value;st.managerBookingTime='';draw()});
    document.getElementById('managerBookingTime')?.addEventListener('change',event=>{st.managerBookingTime=event.target.value;draw()});
  }
};
draw();

// The assessment body mounts inside the existing employee page and reuses its route header.
const injuryReportStorageKey='lflx_injury_reports';
function injuryReports(){try{const value=JSON.parse(localStorage.getItem(injuryReportStorageKey)||'[]');return Array.isArray(value)?value:[]}catch(error){return []}}
for(const record of injuryReports()){
  if(!record.id||!record.appointmentId||!record.customerId)continue;
  if(!st.therapistRecords.some(item=>item.id===record.id))st.therapistRecords.push(record);
  const appointment=therapistAppointment(record.appointmentId);
  if(appointment&&appointment.customerId===record.customerId){appointment.status=record.statusAfterSubmission||'待核销';if(record.redeemed){appointment.redeemed=true;const order=therapistServiceOrder(appointment.orderId);if(order)order.used=Math.max(order.used,1)}}
}
const originalTherapistRecordForm=therapistRecordForm;
therapistRecordForm=function(){
  const appointment=therapistAppointment(st.therapistAppointmentId);
  if(appointment?.type==='评估'&&appointment.service==='运动损伤评估'){
    if(appointment.status!=='服务中')return '<div class="empty">请先开始评估</div>';
    return '<div id="injuryAssessmentMount" style="height:calc(100dvh - 230px);min-height:480px;max-height:760px"></div>';
  }
  return originalTherapistRecordForm();
};
const originalTherapistArchiveReport=therapistArchiveReport;
therapistArchiveReport=function(){
  const customer=therapistCustomer(st.therapistCustomerId);
  if(!customer)return '<div class="empty">未找到客户档案</div>';
  const records=st.therapistRecords.filter(record=>record.customerId===customer.id).concat([
    {type:'评估结果',name:'运动损伤评估',time:'2026-10-30 16:10',title:'首次运动功能评估结果',content:'记录膝关节不适情况，完成基础活动能力评估。'},
    {type:'康复纪要',name:'膝关节运动康复',time:'2026-10-28 11:10',title:'第 2 次康复训练纪要',content:'完成关节活动度练习与下肢力量训练，训练过程无明显不适。'}
  ]).sort((a,b)=>b.time.localeCompare(a.time));
  const report=records[Number(st.therapistArchiveReportIndex)];
  if(!report||report.type!=='评估结果')return '<div class="empty">未找到评估报告</div>';
  if(report.id&&report.answers)return '<div id="injuryAssessmentMount" style="height:calc(100dvh - 180px);min-height:520px;max-height:800px"></div>';
  return `<section class="card"><span class="tag">${therapistEscape(report.type)}</span><h2>${therapistEscape(report.name)}</h2><time>${therapistEscape(report.time)}</time></section><section class="card"><h3>${therapistEscape(report.title)}</h3><p class="therapist-longtext">${therapistEscape(report.content)}</p></section>`;
};
function saveInjuryReport(data){
  const appointment=therapistAppointment(data.appointmentId);
  if(st.page!=='employee'||st.employeeTab!=='therapistRecordForm'||!appointment||appointment.id!==st.therapistAppointmentId||appointment.status!=='服务中'||appointment.type!=='评估'||appointment.service!=='运动损伤评估'||(st.employeeRole==='店长'&&st.employeeType!=='技术型店长'))return;
  if(!data.answers||typeof data.answers!=='object'||Array.isArray(data.answers)||typeof data.summary!=='string')return;
  const createdAt=Date.now(),time=new Date(createdAt).toLocaleString('sv-SE');
  const record={id:'injury-'+appointment.id+'-'+createdAt,customerId:appointment.customerId,appointmentId:appointment.id,orderId:appointment.orderId,type:'评估结果',name:appointment.service,time,title:'运动损伤评估报告',content:data.summary,answers:data.answers,createdAt,redeemed:!!appointment.redeemed,statusAfterSubmission:appointment.redeemed?'已完成':'待核销'};
  try{localStorage.setItem(injuryReportStorageKey,JSON.stringify([record,...injuryReports()]));localStorage.removeItem('lflx_injury_draft_'+appointment.id)}catch(error){toast('保存失败，请检查浏览器存储空间');return}
  st.therapistRecords.unshift(record);appointment.status=record.statusAfterSubmission;
  if(!appointment.redeemed)therapistMessages.unshift({id:'TM'+createdAt,type:'订单核销提醒',time,customerId:appointment.customerId,appointmentId:appointment.id,content:`评估订单 ${appointment.orderId} 待核销。`,unread:true});
  st.therapistRouteStack=[];st.employeeTab=st.employeeRole==='店长'?'managerSchedule':'therapistSchedule';st.therapistScheduleTab='预约服务';st.therapistAppointmentFilter=appointment.status;go('employee');toast(appointment.redeemed?'评估报告已提交，服务完成':'评估报告已提交，等待订单核销');
}
const injuryBaseDraw=draw;
draw=function(){
  injuryBaseDraw();
  const appointment=therapistAppointment(st.therapistAppointmentId);
  const reportView=st.page==='employee'&&st.employeeTab==='therapistArchiveReport';
  const formView=st.page==='employee'&&st.employeeTab==='therapistRecordForm'&&appointment?.service==='运动损伤评估';
  if(formView){document.getElementById('wxTitle').textContent='填写评估资料';document.getElementById('topRoute').textContent='填写评估资料';document.getElementById('noteTitle').textContent='填写评估资料'}
  if(!reportView&&!formView)return;
  const host=document.getElementById('injuryAssessmentMount');
  if(!host||!window.mountInjuryAssessment)return;
  const customer=therapistCustomer(st.therapistCustomerId);
  const records=customer?st.therapistRecords.filter(record=>record.customerId===customer.id).concat([
    {type:'评估结果',name:'运动损伤评估',time:'2026-10-30 16:10',title:'首次运动功能评估结果',content:'记录膝关节不适情况，完成基础活动能力评估。'},
    {type:'康复纪要',name:'膝关节运动康复',time:'2026-10-28 11:10',title:'第 2 次康复训练纪要',content:'完成关节活动度练习与下肢力量训练，训练过程无明显不适。'}
  ]).sort((a,b)=>b.time.localeCompare(a.time)):[];
  const report=reportView?records[Number(st.therapistArchiveReportIndex)]:null;
  if(reportView&&report?.id&&report.answers){
    window.mountInjuryAssessment(host,{report,onSubmit:null});
    return;
  }
  if(formView)window.mountInjuryAssessment(host,{appointmentId:appointment.id,onSubmit:saveInjuryReport});
};
draw();
